namespace Lab04d;

public class Bai4KhachSanForm : Form
{
    TextBox txtHoTen = new(); TextBox txtDiaChi = new(); TextBox txtSoNgay = new(); RadioButton rdoDon = new(); RadioButton rdoDoi = new(); RadioButton rdoBa = new(); CheckBox chkTivi = new(); CheckBox chkInternet = new(); CheckBox chkNuocNong = new(); CheckBox chkKaraoke = new(); CheckBox chkAnSang = new(); TextBox txtThanhTien = new(); TextBox txtSoLuot = new(); TextBox txtTongTien = new(); Button btnThanhToan = new(); Button btnNhapMoi = new(); Button btnTongKet = new(); int tongSoLuot; decimal tongTien;
    public Bai4KhachSanForm()
    {
        Text = "Khách sạn Thanh Thanh"; StartPosition = FormStartPosition.CenterParent;
        TableLayoutPanel content = UiLayout.CreateContent(this, new Size(900, 750), new Size(700, 620)); content.ColumnCount = 1; content.RowCount = 7; content.RowStyles.Add(new RowStyle(SizeType.AutoSize)); for (int i = 0; i < 5; i++) content.RowStyles.Add(new RowStyle(SizeType.AutoSize)); content.RowStyles.Add(new RowStyle(SizeType.Percent, 100)); Label title = UiLayout.Title("KHÁCH SẠN THANH THANH - TRẢ PHÒNG"); title.ForeColor = Color.DarkOrange; content.Controls.Add(title, 0, 0);
        TableLayoutPanel guest = UiLayout.Fields(3, 28); UiLayout.AddField(guest, 0, "Họ và tên:", txtHoTen); UiLayout.AddField(guest, 1, "Địa chỉ:", txtDiaChi); UiLayout.AddField(guest, 2, "Số ngày ở:", txtSoNgay); content.Controls.Add(guest, 0, 1);
        TableLayoutPanel choices = new() { Dock = DockStyle.Fill, AutoSize = true, ColumnCount = 3, RowCount = 1 }; for (int i = 0; i < 3; i++) choices.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100f / 3)); choices.Controls.Add(Choices("Loại phòng", rdoDon, "Phòng đơn", rdoDoi, "Phòng đôi", rdoBa, "Phòng ba"), 0, 0); choices.Controls.Add(Choices("Tiện nghi", chkTivi, "Tivi", chkInternet, "Internet", chkNuocNong, "Máy nước nóng"), 1, 0); choices.Controls.Add(Choices("Dịch vụ", chkKaraoke, "Karaoke", chkAnSang, "Ăn sáng"), 2, 0); content.Controls.Add(choices, 0, 2);
        FlowLayoutPanel actions = UiLayout.ButtonBar(); btnThanhToan = UiLayout.Button("Thanh toán"); btnNhapMoi = UiLayout.Button("Nhập mới"); btnTongKet = UiLayout.Button("Tổng kết"); Button btnThoat = UiLayout.Button("Thoát"); actions.Controls.AddRange(new Control[] { btnThanhToan, btnNhapMoi, btnTongKet, btnThoat }); content.Controls.Add(actions, 0, 3);
        txtThanhTien.ReadOnly = true; txtSoLuot.ReadOnly = true; txtTongTien.ReadOnly = true; TableLayoutPanel summaryFields = new() { Dock = DockStyle.Fill, AutoSize = true, ColumnCount = 4, RowCount = 2 }; summaryFields.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize)); summaryFields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 50)); summaryFields.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize)); summaryFields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 50)); summaryFields.Controls.Add(UiLayout.Label("Thành tiền:"), 0, 0); txtThanhTien.Dock = DockStyle.Fill; summaryFields.Controls.Add(txtThanhTien, 1, 0); summaryFields.Controls.Add(UiLayout.Label("Số lượt:"), 2, 0); txtSoLuot.Dock = DockStyle.Fill; summaryFields.Controls.Add(txtSoLuot, 3, 0); summaryFields.Controls.Add(UiLayout.Label("Tổng tiền:"), 2, 1); txtTongTien.Dock = DockStyle.Fill; summaryFields.Controls.Add(txtTongTien, 3, 1); GroupBox summary = new() { Text = "Thành tiền / Tổng kết", Dock = DockStyle.Fill, AutoSize = true, Padding = new Padding(10) }; summary.Controls.Add(summaryFields); content.Controls.Add(summary, 0, 4);
        btnThanhToan.Enabled = false; btnNhapMoi.Enabled = false; btnTongKet.Enabled = false; txtHoTen.TextChanged += (_, _) => CapNhatNutThanhToan(); txtDiaChi.TextChanged += (_, _) => CapNhatNutThanhToan(); txtSoNgay.TextChanged += (_, _) => CapNhatNutThanhToan(); rdoDon.CheckedChanged += (_, _) => CapNhatNutThanhToan(); rdoDoi.CheckedChanged += (_, _) => CapNhatNutThanhToan(); rdoBa.CheckedChanged += (_, _) => CapNhatNutThanhToan(); txtSoNgay.KeyPress += (_, e) => { if (!char.IsControl(e.KeyChar) && !char.IsDigit(e.KeyChar)) e.Handled = true; }; btnThanhToan.Click += (_, _) => ThanhToan(); btnNhapMoi.Click += (_, _) => ResetForm(); btnTongKet.Click += (_, _) => TongKet(); btnThoat.Click += (_, _) => Close(); FormClosing += (_, e) => { if (MessageBox.Show("Bạn có chắc chắn muốn thoát?", "Xác nhận", MessageBoxButtons.YesNo) == DialogResult.No) e.Cancel = true; }; Load += (_, _) => txtHoTen.Focus();
    }
    private static GroupBox Choices(string title, params object[] entries) { GroupBox group = new() { Text = title, Dock = DockStyle.Fill, AutoSize = true, Padding = new Padding(14), Margin = new Padding(4) }; FlowLayoutPanel list = new() { Dock = DockStyle.Fill, AutoSize = true, FlowDirection = FlowDirection.TopDown, WrapContents = false }; for (int i = 0; i < entries.Length; i += 2) { ButtonBase control = (ButtonBase)entries[i]; control.Text = (string)entries[i + 1]; control.AutoSize = true; control.Margin = new Padding(3); list.Controls.Add(control); } group.Controls.Add(list); return group; }
    private void CapNhatNutThanhToan() => btnThanhToan.Enabled = !string.IsNullOrWhiteSpace(txtHoTen.Text) && !string.IsNullOrWhiteSpace(txtDiaChi.Text) && int.TryParse(txtSoNgay.Text, out int soNgay) && soNgay > 0 && (rdoDon.Checked || rdoDoi.Checked || rdoBa.Checked);
    private void ThanhToan() { if (!int.TryParse(txtSoNgay.Text, out int soNgay) || soNgay <= 0) { MessageBox.Show("Số ngày ở không hợp lệ."); return; } decimal giaPhong; if (rdoDon.Checked) giaPhong = 300000; else if (rdoDoi.Checked) giaPhong = 350000; else if (rdoBa.Checked) giaPhong = 400000; else { MessageBox.Show("Vui lòng chọn loại phòng."); return; } decimal tienPhong = giaPhong * soNgay, tienTienNghi = 0, tienDichVu = 0; if (chkTivi.Checked) tienTienNghi += 10000; if (chkInternet.Checked) tienTienNghi += 10000; if (chkNuocNong.Checked) tienTienNghi += 10000; if (chkKaraoke.Checked) tienDichVu += 50000; if (chkAnSang.Checked) tienDichVu += 15000 * soNgay; decimal thanhTien = tienPhong + tienTienNghi + tienDichVu; txtThanhTien.Text = thanhTien.ToString("N0") + " VNĐ"; tongSoLuot++; tongTien += thanhTien; btnNhapMoi.Enabled = true; btnTongKet.Enabled = true; btnThanhToan.Enabled = false; }
    private void ResetForm() { txtHoTen.Clear(); txtDiaChi.Clear(); txtSoNgay.Clear(); rdoDon.Checked = false; rdoDoi.Checked = false; rdoBa.Checked = false; chkTivi.Checked = false; chkInternet.Checked = false; chkNuocNong.Checked = false; chkKaraoke.Checked = false; chkAnSang.Checked = false; txtThanhTien.Clear(); btnNhapMoi.Enabled = false; btnThanhToan.Enabled = false; txtHoTen.Focus(); }
    private void TongKet() { txtSoLuot.Text = tongSoLuot.ToString(); txtTongTien.Text = tongTien.ToString("N0") + " VNĐ"; MessageBox.Show($"Tổng số lượt khách: {tongSoLuot}\nTổng tiền trong ngày: {tongTien:N0} VNĐ", "Tổng kết"); tongSoLuot = 0; tongTien = 0; btnTongKet.Enabled = false; }
}
